def check_plan(reply):
    problems = []
    done = reply.get('done')
    if isinstance(done, str):
        done = done.strip().lower() == 'true'
    calls = []
    for i, c in enumerate(reply.get('tool_calls') or []):
        if not isinstance(c, dict):
            problems.append(f'tool_calls[{i}] was not an object')
            continue
        calls.append(c)
    return {'done': done is True, 'tool_calls': calls}, problems

